const fs = require('fs');
const path = require('path');

const siteDir = path.join(__dirname, '..', 'site');
const files = fs.readdirSync(siteDir).filter(f => f.endsWith('.html'));

// decode URL-encoded filenames, match to actual file
const fileMap = new Map(); // lowercase filename -> actual filename
for (const f of files) fileMap.set(decodeURIComponent(f).toLowerCase(), f);

function read(f) {
  return fs.readFileSync(path.join(siteDir, f), 'utf8');
}

function extract(html) {
  const h1 = (html.match(/<h1>([^<]+)<\/h1>/) || [])[1];
  const tema = (html.match(/<p class="tema">Tema:\s*([^<]+)<\/p>/) || [])[1];
  // links inside <section id="sinonimos"> and id="analogas"
  const rels = {};
  for (const sec of ['sinonimos', 'analogas']) {
    const m = html.match(new RegExp(`<section id="${sec}">([\\s\\S]*?)</section>`));
    rels[sec] = [];
    if (m) {
      for (const a of m[1].matchAll(/<a href="([^"]+)">([^<]+)<\/a>/g)) {
        rels[sec].push({ href: decodeURIComponent(a[1]), text: a[2] });
      }
    }
  }
  return { h1, tema, rels };
}

// redirect pages: meta refresh target
const redirects = new Map();
for (const f of files) {
  const html = read(f);
  const m = html.match(/<meta http-equiv="refresh" content="0; url=([^"]+)"/);
  if (m) redirects.set(decodeURIComponent(f).toLowerCase(), decodeURIComponent(m[1]).toLowerCase());
}
const resolve = (fname) => {
  let f = fname.toLowerCase(), seen = new Set();
  while (redirects.has(f) && !seen.has(f)) { seen.add(f); f = redirects.get(f); }
  return f;
};

// Pass 1: identify word pages and their canonical h1
const pages = new Map(); // filename(lower) -> {word, tema}
for (const f of files) {
  const { h1, tema } = extract(read(f));
  if (h1 && tema) pages.set(decodeURIComponent(f).toLowerCase(), { word: h1.trim(), tema: tema.trim() });
}

// Pass 2: relations
const words = new Map(); // word -> Set of linked words
const addRel = (a, b) => {
  if (!words.has(a)) words.set(a, new Set());
  if (!words.has(b)) words.set(b, new Set());
  words.get(a).add(b); words.get(b).add(a);
};
const temas = new Map();
let dangling = [];

for (const [fname, info] of pages) {
  temas.set(info.word, info.tema);
  const { rels } = extract(read(fileMap.get(fname) || fname));
  for (const list of Object.values(rels)) {
    for (const l of list) {
      const target = resolve(l.href);
      if (pages.has(target)) addRel(info.word, pages.get(target).word);
      else if (target !== 'rascunho-3.html' && !redirects.has(target)) dangling.push(info.word + ' -> ' + l.href);
    }
  }
}

// normalize: if two words differ only by case, merge (keep the more common casing? keep first, merge sets)
const canon = new Map(); // lower -> chosen word
for (const w of words.keys()) {
  const lw = w.toLowerCase();
  if (!canon.has(lw)) canon.set(lw, w);
}
const merged = new Map(); // canonical word -> Set
for (const [w, set] of words) {
  const c = canon.get(w.toLowerCase());
  if (!merged.has(c)) merged.set(c, new Set());
  for (const t of set) merged.get(c).add(canon.get(t.toLowerCase()));
}

// words.json: word -> sorted list of linked words
const out = {};
const sortedWords = [...merged.keys()].sort((a, b) => a.localeCompare(b, 'pt'));
for (const w of sortedWords) {
  out[w] = [...merged.get(w)].sort((a, b) => a.localeCompare(b, 'pt'));
}
fs.writeFileSync(path.join(__dirname, '..', 'words.json'), JSON.stringify(out, null, 2), 'utf8');

// result.json
let pairSet = new Set();
for (const [w, set] of merged) for (const t of set) {
  const [x, y] = [w, t].sort();
  pairSet.add(x + '\u0000' + y);
}
let most = [...merged.entries()].map(([w, s]) => [w, s.size]).sort((a, b) => b[1] - a[1]).slice(0, 10);
const result = {
  words: merged.size,
  relations: pairSet.size,
  most_connected: Object.fromEntries(most),
};
fs.writeFileSync(path.join(__dirname, '..', 'result.json'), JSON.stringify(result, null, 2), 'utf8');

console.log('pages:', files.length, 'wordPages:', pages.size, 'words:', merged.size, 'pairs:', pairSet
