--- tmp/page.js ---
const fs = require('fs');
const words = JSON.parse(fs.readFileSync('words.json', 'utf8'));
const temas = JSON.parse(fs.readFileSync('tmp/word-tema.json', 'utf8'));
const data = {};
for (const w of Object.keys(words)) data[w] = { tema: temas[w] || 'outros', rel: words[w] };
const html = fs.readFileSync('tmp/template.html', 'utf8')
  .replace('250 palavras · 743 ligações',
    `${Object.keys(words).length} palavras · ${JSON.parse(fs.readFileSync('result.json','utf8')).relations} ligações`)
  .replace('__DATA__', JSON.stringify(data).replace(/</g, '\\u003c'));
fs.writeFileSync('universe/index.html', html, 'utf8');
console.log('written', html.length, 'bytes,', Object.keys(data).length, 'words');


